package com.aistock.prediction.comparison;
import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static com.aistock.prediction.comparison.ComparisonRecords.*;import static com.aistock.prediction.comparison.ComparisonTestEvidence.*;
class ComparisonServiceTest {
 @Test void busyDoesNotCreateOperationAndFinishedReadsBypassGate()throws Exception{var r=mock(ComparisonRepository.class);var m=mock(ComparisonMarketClient.class);var clock=Clock.fixed(Instant.parse("2026-10-13T00:00:00Z"),ZoneOffset.UTC);var u=UUID.randomUUID();var a=sample("SH600030",new String[]{"10","11","12"},new String[]{"1","2","3"});var b=sample("SH600276",new String[]{"10","11","12"},new String[]{"1","2","3"});var in=new Input(UUID.randomUUID(),List.of("SH600030","SH600276"),LocalDate.parse("2026-07-09"),LocalDate.parse("2026-10-09"),List.of(UUID.fromString(a.path("evidenceId").asText()),UUID.fromString(b.path("evidenceId").asText())));var running=new Operation(in.requestId(),"RUNNING",null,null,clock.instant().plusSeconds(45),false);when(r.claim(eq(u),eq(in),any())).thenReturn(new ComparisonRepository.Claim(true,UUID.randomUUID(),running,true));var entered=new CountDownLatch(1);var release=new CountDownLatch(1);when(m.evidence(any())).thenAnswer(call->{entered.countDown();release.await(5,TimeUnit.SECONDS);return call.getArgument(0).equals(in.evidenceIds().get(0))?a:b;});var done=new Operation(in.requestId(),"SUCCEEDED",UUID.randomUUID(),null,null,false);when(r.complete(eq(u),eq(in),any(),any(),anyList(),any())).thenReturn(done);var service=new ComparisonService(r,m,M,clock,1);var pool=Executors.newSingleThreadExecutor();try{var task=pool.submit(()->service.create(u,in));assertTrue(entered.await(5,TimeUnit.SECONDS));var another=new Input(UUID.randomUUID(),in.instrumentIds(),in.from(),in.to(),in.evidenceIds());var ex=assertThrows(com.aistock.common.BusinessException.class,()->service.create(u,another));assertEquals("COMPARISON_BUSY",ex.code());verify(r,never()).claim(eq(u),eq(another),any());when(r.replay(eq(u),eq(another),any())).thenReturn(done);assertEquals("SUCCEEDED",service.create(u,another).operation().state());release.countDown();assertEquals("SUCCEEDED",task.get(5,TimeUnit.SECONDS).operation().state());}finally{release.countDown();pool.shutdownNow();}}
 @Test void readingSavedResultNeverRefreshesMarketEvidence(){
  var repo=mock(ComparisonRepository.class);var market=mock(ComparisonMarketClient.class);var owner=UUID.randomUUID();var id=UUID.randomUUID();
  var saved=M.createObjectNode().put("comparisonId",id.toString()).put("sourceHash","a".repeat(64)).put("to","2026-10-09");
  when(repo.get(owner,id)).thenReturn(saved);
  var service=new ComparisonService(repo,market,M,Clock.fixed(Instant.parse("2026-10-14T00:00:00Z"),ZoneOffset.UTC),1);
  assertEquals("2026-10-09",service.get(owner,id).path("to").asText());assertEquals("a".repeat(64),service.get(owner,id).path("sourceHash").asText());
  verifyNoInteractions(market);verify(repo,times(2)).get(owner,id);
 }
}
